package org.jlinalg.cli;

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.nio.file.attribute.BasicFileAttributes;
import java.time.Instant;
import java.util.*;
import static org.jlinalg.cli.Monocle3WorkflowRequest.*;

/** Original CellPhoneDB workflows with independent native checks and atomic batch admission. */
public final class CellPhoneDbWorkflowCli {
    private CellPhoneDbWorkflowCli() { }
    static final String ACTION="Require exit0 AND analysis-status.json result_admitted=true. Read WARNINGS.md, every native-input-dispositions.json, subsampling-state.json when present, original stdout/stderr, original-error.traceback and process receipts. FAIL2 admits no result from the whole requested batch, including earlier completed cases. Preserve all originals/provisionals, correct the named input, source-method, precision, runtime, timeout or capacity cause, then retry NEW paths. SKIP3 skips dependent analysis: use the separate explicit CellPhoneDbSetupCli EXPORT and permitted INSTALL with the exact Linux x86_64 dependencies. If installation is forbidden, keep analysis skipped. RUN installs nothing. No edition fallback, identifier repair, expression normalization, differential-expression fitting, species conversion, inferred paper parameters or biological/paper-reproduction claim occurs. Original debug pickles remain opaque and are never loaded. Scoring, CellSign, random draws and subsampling geometry remain original upstream implementations. Full-method subsampling reseeds from entropy; its source failure/full-count fallback requires an explicit policy. Sampling is not made deterministic by the global/permutation seeds. Runtime supervision bounds wall time/output/owned processes, not OS memory or CPU consumption.";
    record Captured(Path source,Path copy,NextflowFiles.Pin pin) { }
    public static void main(String[] args){System.exit(run(args,System.out,System.err));}
    public static int run(String[] args,PrintStream output,PrintStream error){
        if(args.length==1&&args[0].equals("--help")){output.println("java -cp DEVELOPMENT.jar org.jlinalg.cli.CellPhoneDbWorkflowCli --request request.json\nOriginal CellPhoneDB5.0.1 simple, statistical or supplied-DEG workflows on explicit CSV/TSV/H5AD expression, CSV/TSV metadata and a supplied data-only database ZIP. Linux x86_64 execution; portable native Java preparation/statistics APIs. Use explicit source-compatible normalized expression and every scientific option; no defaults are inferred from a paper.\n"+ACTION);return 0;}
        Path out=null;int exit=2;var warnings=new ArrayList<String>();warnings.add(ACTION);var state=new LinkedHashMap<String,Object>();state.put("status","RUNNING_NO_RESULT_ADMITTED");state.put("result_admitted",false);state.put("started_at",Instant.now().toString());state.put("required_action",ACTION);
        try{
            require(args.length==2&&args[0].equals("--request"),"Use --request FILE or --help");Path requestPath=Path.of(args[1]).toAbsolutePath().normalize();byte[] raw=NextflowFiles.bytes(requestPath,16777216);var requestPin=new NextflowFiles.Pin(raw.length,NextflowFiles.sha(raw));require(requestPin.equals(NextflowFiles.pin(requestPath,16777216,()->{})),"Original request changed during capture");var request=CellPhoneDbWorkflowRequest.parse(object(NextflowParameters.parse(NextflowFiles.utf8(raw),16777216,2000000)),requestPath.getParent());Path wanted=request.out();require(!Files.exists(wanted,LinkOption.NOFOLLOW_LINKS)&&canonicalMissing(wanted).equals(wanted),"Require NEW output under canonical unlinked parents");require(!requestPath.startsWith(wanted)&&!request.runtime().startsWith(wanted),"Output overlaps original request/runtime receipt");for(var input:request.inputs())require(!wanted.startsWith(input.source())&&!input.source().startsWith(wanted),"Output overlaps an original input");
            if(Files.isRegularFile(request.runtime(),LinkOption.NOFOLLOW_LINKS)){var quick=CellPhoneDbWorkflowRuntime.read(request.runtime(),67108864);if(quick.get("runtime_environment") instanceof String value){Path root=canonicalMissing(Path.of(value).toAbsolutePath().normalize());require(!wanted.startsWith(root)&&!root.startsWith(wanted),"Output overlaps the read-only original runtime tree");}}
            Files.createDirectories(wanted.getParent());Files.createDirectory(wanted);out=wanted;Files.write(out.resolve("request.original.json"),raw,StandardOpenOption.CREATE_NEW);status(out,state);error.println("CellPhoneDB: verifying exact original dependencies; the whole batch remains unadmitted.");var runtime=CellPhoneDbWorkflowRuntime.prepare(request);require(!out.startsWith(runtime.prefix())&&!runtime.prefix().startsWith(out),"Output overlaps original runtime");Path inputHome=Files.createDirectory(out.resolve("inputs"));var captured=new ArrayList<Captured>();var paths=new LinkedHashMap<String,Path>();var captureRecords=new ArrayList<Object>();long bytes=0;int files=0;
            for(var input:request.inputs()){
                require(++files<=request.maximumFiles(),"Complete input member capacity exceeded");Path copy=inputHome.resolve(input.id()+"."+input.format());var pin=NextflowFiles.pin(input.source(),request.inputBytes()-bytes,()->{});Files.copy(input.source(),copy);require(pin.equals(NextflowFiles.pin(copy,request.inputBytes()-bytes,()->{}))&&pin.equals(NextflowFiles.pin(input.source(),request.inputBytes()-bytes,()->{})),"Original/captured input changed during complete byte copy");bytes=Math.addExact(bytes,pin.bytes());captured.add(new Captured(input.source(),copy,pin));paths.put(input.id(),copy);captureRecords.add(Map.of("id",input.id(),"source",input.source().toString(),"captured",copy.toString(),"declared_format",input.format(),"bytes",pin.bytes(),"sha256",pin.sha256()));
            }
            NextflowFiles.writeJson(out.resolve("input-capture.json"),captureRecords);var preflight=CellPhoneDbWorkflowInputs.preflight(request,paths);CellPhoneDbWorkflowRuntime.sources(out.resolve("source"));var effective=request.worker(paths);NextflowFiles.writeJson(out.resolve("effective-request.json"),effective);error.println("CellPhoneDB: executing every explicit original method; results remain provisional.");var report=CellPhoneDbWorkflowRuntime.execute(out.resolve("worker"),request,runtime,effective);var meter=new CellPhoneDbWorkflowAudit.Meter(request.auditOperations());var audits=new ArrayList<Object>();var cases=list(report.get("cases"));require(cases.size()==request.analyses().size(),"Original case family incomplete");
            for(int i=0;i<cases.size();i++){
                var result=object(cases.get(i));var specification=request.analyses().get(i);String id=text(specification.get("id"));require(text(result.get("id")).equals(id)&&text(result.get("method")).equals(text(specification.get("method"))),"Original cases reordered or changed method");Path home=out.resolve("worker").resolve(id);audits.add(CellPhoneDbWorkflowAudit.analyze(specification,home,preflight.metadata().get(id),request,warnings,meter));
            }
            warnings.add("Read worker/original.stdout and worker/original.stderr verbatim even when the batch passed. Original source diagnostic suppression is unchanged. Source-generated pickle files are retained for provenance only and are not audit inputs.");NextflowFiles.writeJson(out.resolve("native-audit.json"),Map.of("cases",audits,"audit_operations",meter.used,"numeric_cells",meter.numeric,"identity_states",meter.identities,"tsv_cells",meter.tsv,"independent_random_generator",false,"pickle_deserialized",false));error.println("CellPhoneDB: rechecking all original inputs, source members and complete runtime tree before admission.");runtime.verify();CellPhoneDbWorkflowRuntime.verifySources(out.resolve("source"));for(var input:captured)require(input.pin().equals(NextflowFiles.pin(input.source(),request.inputBytes(),()->{}))&&input.pin().equals(NextflowFiles.pin(input.copy(),request.inputBytes(),()->{})),"Original/captured input changed during analysis");require(requestPin.equals(NextflowFiles.pin(requestPath,16777216,()->{})),"Original request changed during analysis");state.put("status","PASS_ORIGINAL_CELLPHONEDB_WORKFLOWS");state.put("edition",request.edition());state.put("cases",audits);state.put("paper_reproduced",false);state.put("atomic_batch",true);state.put("finished_at",Instant.now().toString());warnings(out,state,warnings);NextflowFiles.writeJson(out.resolve("manifest.json"),manifest(out,request));state.put("manifest_sha256",NextflowFiles.pin(out.resolve("manifest.json"),67108864,()->{}).sha256());state.put("result_admitted",true);status(out,state);exit=0;output.println("CellPhoneDB complete batch admitted: "+out+"\nRead WARNINGS.md and analysis-status.json before using results.");
        }catch(CellPhoneDbWorkflowRuntime.Unavailable failure){exit=3;state.put("status","SKIP3_CELLPHONEDB_DEPENDENCIES_UNAVAILABLE");state.put("error",failure.toString());warnings.add(failure.toString());error.println("CELLPHONEDB SKIP3: "+failure+"\nREQUIRED ACTION: "+ACTION);}
        catch(Exception failure){state.put("status","FAIL2_NO_RESULT_ADMITTED");state.put("error",failure.toString());warnings.add(failure.toString());error.println("CELLPHONEDB FAIL2: "+failure+"\nREQUIRED ACTION: "+ACTION);}
        catch(OutOfMemoryError failure){state.put("status","FAIL2_JAVA_HEAP_EXHAUSTED");state.put("error",failure.toString());warnings.add("Java heap exhausted; no partial native audit or original batch is admitted.");error.println("CELLPHONEDB FAIL2: Java heap exhausted. "+ACTION);}
        finally{if(exit!=0&&out!=null){state.put("result_admitted",false);state.put("finished_at",Instant.now().toString());try{warnings(out,state,warnings);status(out,state);}catch(IOException failure){error.println("CELLPHONEDB FAIL2: failure receipt could not be finalized: "+failure+". Preserve the whole unadmitted directory.");exit=2;}}if(out!=null)error.println("WARNINGS / REQUIRED ACTIONS: "+out.resolve("WARNINGS.md"));}return exit;
    }
    private static Map<String,Object> manifest(Path root,CellPhoneDbWorkflowRequest.Request request)throws IOException {
        var files=new TreeMap<String,Object>();var directories=new TreeSet<String>();long[] bytes={0};int[] count={0};Files.walkFileTree(root,new SimpleFileVisitor<>(){
            private void capacity(long size)throws IOException{require(++count[0]<=request.maximumFiles()&&size<=request.outputBytes()-bytes[0],"Complete output capacity exceeded; no partial family is admitted");bytes[0]+=size;}
            @Override public FileVisitResult preVisitDirectory(Path path,BasicFileAttributes attrs)throws IOException{if(!path.equals(root)){capacity(0);directories.add(root.relativize(path).toString().replace('\\','/'));}return FileVisitResult.CONTINUE;}
            @Override public FileVisitResult visitFile(Path path,BasicFileAttributes attrs)throws IOException{String name=root.relativize(path).toString().replace('\\','/');if(name.equals("analysis-status.json")||name.equals("manifest.json"))return FileVisitResult.CONTINUE;require(attrs.isRegularFile()&&!attrs.isSymbolicLink(),"Linked/nonregular original output is outside this workflow profile");capacity(attrs.size());files.put(name,CellPhoneDbWorkflowRuntime.pinObject(NextflowFiles.pin(path,request.outputBytes(),()->{})));return FileVisitResult.CONTINUE;}
        });return Map.of("schema_version",1,"directories",directories,"files",files,"captured_bytes",bytes[0],"result_admission","Require analysis-status.json result_admitted=true; original bytes, typed data-only snapshots and all source reports remain retained.");
    }
    private static Path canonicalMissing(Path path)throws IOException{var suffix=new ArrayDeque<Path>();Path current=path;while(!Files.exists(current,LinkOption.NOFOLLOW_LINKS)){require(current.getParent()!=null,"Missing canonical output ancestor");suffix.addFirst(current.getFileName());current=current.getParent();}current=current.toRealPath();for(Path part:suffix)current=current.resolve(part);return current;}
    private static void status(Path out,Map<String,Object> state)throws IOException{Path temporary=out.resolve(".analysis-status-"+UUID.randomUUID()+".tmp");Files.writeString(temporary,NextflowJson.json(state)+"\n",StandardCharsets.UTF_8,StandardOpenOption.CREATE_NEW);Files.move(temporary,out.resolve("analysis-status.json"),StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);}
    private static void warnings(Path out,Map<String,Object> state,List<String> messages)throws IOException{Files.writeString(out.resolve("WARNINGS.md"),"# "+state.get("status")+"\n\n"+String.join("\n\n",messages)+"\n\nRequired action: "+ACTION+"\n",StandardCharsets.UTF_8,StandardOpenOption.CREATE,StandardOpenOption.TRUNCATE_EXISTING);}
}
